import { createController } from './ui/controller.js';
import { busSvgMarkup, catSvgMarkup } from './ui/render.js';
import { preloadBgm } from './ui/sound.js';

// 开始页示例巴士/猫咪与游戏内视觉统一（同一 SVG 素材，纯视觉初始化）
