/* ===== 《猫咪巴士大疏通》样式 =====
   视觉方向：暖色街景 + 玩具质感的 2.5D 巴士 + 圆润猫咪。
   所有素材为内联 SVG，无远程字体/图片依赖。 */

:root {
  --bg: #f0e2c8;
  --bg-2: #e6d2b2;
  --card: #fffaf0;
  --card-2: #fffdf8;
  --ink: #33291c;
  --ink-soft: #8b7b62;
  --accent: #ff9f43;
  --accent-deep: #e98522;
  --accent-soft: #ffd166;
  --danger: #e8554d;
  --hairline: #eadcc2;
  --asphalt: #3e464f;
  --slot-bg: #f3e8d2;

  --bus-red: #e94f4f;
  --bus-blue: #4a8fe8;
  --bus-green: #42b96a;
  --bus-purple: #9a6bd6;
  --bus-cyan: #2fbfc4;
  --bus-orange: #f08a2a;
  --bus-yellow: #e9bf35;
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; padding: 0; height: 100%; }
html { overflow: hidden; overscroll-behavior: none; }
body {
  background:
    radial-gradient(1100px 700px at 18% -10%, #fff3d6 0%, rgba(255,243,214,0) 60%),
    radial-gradient(900px 600px at 100% 100%, #dfc79f 0%, rgba(223,199,159,0) 55%),
    linear-gradient(160deg, var(--bg) 0%, var(--bg-2) 100%);
  color: var(--ink);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, sans-serif;
  display: flex; justify-content: center;
  user-select: none; -webkit-user-select: none;
  overflow: hidden; overscroll-behavior: none;
}

#app {
  width: 100%; max-width: 760px;
  height: var(--app-height, 100dvh);
  max-height: var(--app-height, 100dvh);
  min-height: 0;
  display: flex; flex-direction: column;
  position: relative; overflow: hidden;
}

.hidden { display: none !important; }

/* ===== 通用按钮 ===== */
.btn {
  border: none; cursor: pointer; font-family: inherit;
  border-radius: 12px; font-size: 15px; font-weight: 700;
  padding: 9px 16px; color: #fff;
  transition: transform .12s, filter .12s, box-shadow .12s;
  touch-action: manipulation;
}
.btn:active { transform: scale(.96); filter: brightness(.97); }
.btn:disabled, .btn.disabled {
  opacity: .45; box-shadow: none; transform: none;
  cursor: not-allowed; filter: grayscale(.35);
}
.btn-primary { background: linear-gradient(180deg, #ffb35c, var(--accent-deep)); box-shadow: 0 4px 0 #c36e12, 0 8px 18px rgba(210,120,20,.25); }
.btn-primary:active { box-shadow: 0 1px 0 #c36e12; }
.btn-primary:disabled { box-shadow: none; }
.btn-ghost { background: #f6ecd8; color: var(--ink); box-shadow: 0 3px 0 #d9c9a7; border: 1px solid #eadcc2; }
.btn-ghost:active { box-shadow: 0 1px 0 #d9c9a7; }
.btn-big { font-size: 19px; padding: 14px 46px; border-radius: 16px; }

/* ===== 开始页（只保留标题 / 一句说明 / 开始按钮 / 音乐开关） ===== */
#screen-start {
  flex: 1; display: flex; align-items: center; justify-content: center;
  padding:
    calc(16px + env(safe-area-inset-top))
    calc(18px + env(safe-area-inset-right))
