/**
 * One-off mobile smoke check over Chrome DevTools Protocol (no npm deps).
 * Usage: node /path/to/script.mjs http://127.0.0.1:4173
 */
import { spawn } from 'node:child_process';
import { mkdir, writeFile } from 'node:fs/promises';
import { setTimeout as sleep } from 'node:timers/promises';

const BASE = process.argv[2] || 'http://127.0.0.1:4173';
const PORT = 9333;
const OUT = '/private/var/folders/rh/4ql33s5x59vcqrjl7nycnkn80000gn/T/opencode/mobile-check';
const CHROME = '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome';

await mkdir(OUT, { recursive: true });

const chrome = spawn(CHROME, [
  '--headless=new',
  `--remote-debugging-port=${PORT}`,
  '--remote-allow-origins=*',
  `--user-data-dir=${OUT}/profile`,
  '--no-first-run',
  '--no-default-browser-check',
  '--disable-background-timer-throttling',
  '--disable-renderer-backgrounding',
  '--disable-gpu',
  '--hide-scrollbars',
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] });

let chromeErr = '';
chrome.stderr.on('data', (d) => { chromeErr += d; });

async function waitForDebugger() {
  for (let i = 0; i < 100; i++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/list`);
      if (res.ok) return res.json();
    } catch {}
    await sleep(100);
  }
  throw new Error(`Chrome debugger not ready\n${chromeErr}`);
}

class CDP {
  constructor(wsUrl) {
    this.ws = new WebSocket(wsUrl);
    this.id = 0;
    this.pending = new Map();
    this.events = new Map();
    this.ready = new Promise((resolve, reject) => {
      this.ws.addEventListener('open', resolve);
      this.ws.addEventListener('error', reject);
    });
    this.ws.addEventListener('message', (event) => {
      const msg = JSON.parse(event.data);
      if (msg.id) {
        const p = this.pending.get(msg.id);
        if (!p) return;
        this.pending.delete(msg.id);
        if (msg.error) p.reject(new Error(`${msg.error.message} ${msg.error.data || ''}`));
        else p.resolve(msg.result);
      } else {
        for (const fn of this.events.get(msg.method) || []) fn(msg.params);
      }
    });
  }
  send(method, params = {}) {
    const id = ++this.id;
    this.ws.send(JSON.stringify({ id, method, params }));
    return new Promise((resolve, reject) => this.pending.set(id, { resolve, reject }));
  }
  on(method, fn) {
    if (!this.events.has(method)) this.events.set(method, []);
    this.events.get(method).push(fn);
  }
  close() { this.ws.close(); }
}

const tabs = await waitForDebugger();
const page = tabs.find((t) => t.type === 'page');
const cdp = new CDP(page.webSocketDebuggerUrl);
await cdp.ready;

const consoleErrors = [];
const pageErrors = [];
const failedRequests = [];
cdp.on('Runtime.consoleAPICalled', (p) => {
  if (p.type === 'error') consoleErrors.push(p.args.map((a) => a.value ?? a.description).join(' '));
});
cdp.on('Runtime.exceptionThrown', (p) => {
  pageErrors.push(p.exceptionDetails.exception?.description || p.exceptionDetails.text);
});
cdp.on('Network.loadingFailed', (p) => {
  if (!p.canceled) failedRequests.push(`${p.errorText} ${p.type}`);
});
cdp.on('Network.responseReceived', (p) => {
  if (p.response.status >= 400) failedRequests.push(`HTTP ${p.response.status} ${p.response.url}`);
});

await Promise.all([
  cdp.send('Page.enable'),
  cdp.send('Runtime.enable'),
  cdp.send('Network.enable'),
  cdp.send('Log.enable'),
]);

async function waitLoad() {
  const loaded = new Promise((resolve) => {
    const fn = () => { cdp.events.set('Page.loadEventFired', (cdp.events.get('Page.loadEventFired') || []).filter((x) => x !== fn)); resolve(); };
    cdp.on('Page.loadEventFired', fn);
  });
  await Promise.race([loaded, sleep(15000)]);
  await sleep(400);
}

async function evaluate(script) {
  const res = await cdp.send('Runtime.evaluate', {
    expression: script,
    returnByValue: true,
    awaitPromise: true,
  });
  if (res.exceptionDetails) throw new Error(res.exceptionDetails.exception?.description || res.exceptionDetails.text);
  return res.value;
}

async function tapSelector(selector) {
  const rect = await evaluate(`(() => {
    const el = document.querySelector(${JSON.stringify(selector)});
    if (!el) return null;
    const r = el.getBoundingClientRect();
    return { x: r.x + r.width / 2, y: r.y + r.height / 2, w: r.width, h: r.height };
  })()`);
  if (!rect) throw new Error(`missing ${selector}`);
  if (rect.w < 2 || rect.h < 2) throw new Error(`zero-size ${selector}`);
  await cdp.send('Input.dispatchMouseEvent', { type: 'mouseMoved', x: rect.x, y: rect.y });
  await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: rect.x, y: rect.y, button: 'left', buttons: 1, clickCount: 1 });
  await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: rect.x, y: rect.y, button: 'left', buttons: 0, clickCount: 1 });
  await sleep(250);
  return rect;
}

async function screenshot(name) {
  const { data } = await cdp.send('Page.captureScreenshot', { format: 'png', fromSurface: true });
  await writeFile(`${OUT}/${name}.png`, Buffer.from(data, 'base64'));
}

const UA = {
  ios: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.5 Mobile/15E148 Safari/604.1',
  android: 'Mozilla/5.0 (Linux; Android 14; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/126.0.0.0 Mobile Safari/537.36',
  wechat: 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_5 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Mobile/15E148 MicroMessenger/8.0.50(0x18003234) NetType/WIFI Language/zh_CN',
};

const devices = [
  { name: 'iphone-se-375x667', width: 375, height: 667, dpr: 2, ua: UA.ios },
  { name: 'iphone-14pro-393x852', width: 393, height: 852, dpr: 3, ua: UA.ios },
  { name: 'pixel7-412x915', width: 412, height: 915, dpr: 2.625, ua: UA.android },
  { name: 'wechat-390x844', width: 390, height: 844, dpr: 3, ua: UA.wechat },
  { name: 'small-320x568', width: 320, height: 568, dpr: 2, ua: UA.android },
];

const metricsExpr = `(() => {
  const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return {
    x: +r.x.toFixed(1), y: +r.y.toFixed(1), w: +r.width.toFixed(1), h: +r.height.toFixed(1),
    right: +r.right.toFixed(1), bottom: +r.bottom.toFixed(1),
    inView: r.top >= -1 && r.left >= -1 && r.right <= innerWidth + 1 && r.bottom <= innerHeight + 1,
  }; };
  const visible = (el) => !!(el && el.getClientRects().length && getComputedStyle(el).visibility !== 'hidden');
  const key = ['#btn-start', '#btn-music-home', '#hud', '#hud-level', '#queue', '#slots', '#board', '#btn-restart', '#btn-hint', '#btn-rescue', '#btn-mute', '#btn-music'];
  const rects = Object.fromEntries(key.map((s) => [s, rect(document.querySelector(s))]));
  const buses = [...document.querySelectorAll('#board .bus')].map((el) => ({ id: el.dataset.busId, ...rect(el) }));
  const overlaps = [];
  for (let i = 0; i < buses.length; i++) for (let j = i + 1; j < buses.length; j++) {
    const a = buses[i], b = buses[j];
    const ox = Math.min(a.right, b.right) - Math.max(a.x, b.x);
    const oy = Math.min(a.bottom, b.bottom) - Math.max(a.y, b.y);
    if (ox > 4 && oy > 4) overlaps.push(a.id + '/' + b.id + ':' + ox.toFixed(0) + 'x' + oy.toFixed(0));
  }
  const screen = document.querySelector('#screen-game:not(.hidden)') ? 'game' : document.querySelector('#screen-start:not(.hidden)') ? 'start' : document.querySelector('#screen-levels:not(.hidden)') ? 'levels' : 'unknown';
  return {
    screen,
    innerWidth, innerHeight,
    docScrollWidth: document.documentElement.scrollWidth,
    docScrollHeight: document.documentElement.scrollHeight,
    bodyScrollWidth: document.body.scrollWidth,
    horizontalOverflow: document.documentElement.scrollWidth > innerWidth + 1 || document.body.scrollWidth > innerWidth + 1,
    appHeight: getComputedStyle(document.querySelector('#app')).height,
    appRect: rect(document.querySelector('#app')),
    rects,
    buses,
    busOverlaps: overlaps,
    visibleKey: Object.fromEntries(key.map((s) => [s, visible(document.querySelector(s))])),
    state: window.__game ? {
      level: window.__game.level?.id,
      moves: window.__game.state?.moves,
      bgmPlaying: window.__game.bgmPlaying,
      bgmMuted: window.__game.bgmMuted,
      bgmMode: window.__game.bgmMode,
    } : null,
    resources: performance.getEntriesByType('resource').map((r) => ({
      name: r.name.replace(location.origin, ''),
      transferSize: r.transferSize,
      duration: +r.duration.toFixed(1),
    })).filter((r) => /bgm|\\.js|\\.css|favicon/.test(r.name)),
  };
})()`;

const report = { base: BASE, devices: {} };
let hardFail = false;

for (const dev of devices) {
  const result = { checks: [], errors: [] };
  const check = (name, ok, detail) => {
    result.checks.push({ name, ok: !!ok, detail });
    if (!ok) hardFail = true;
  };

  await cdp.send('Emulation.setDeviceMetricsOverride', {
    width: dev.width, height: dev.height, deviceScaleFactor: dev.dpr, mobile: true,
    screenWidth: dev.width, screenHeight: dev.height,
    screenOrientation: { type: 'portraitPrimary', angle: 0 },
  });
  await cdp.send('Emulation.setTouchEmulationEnabled', { enabled: true, maxTouchPoints: 5 });
  await cdp.send('Emulation.setUserAgentOverride', { userAgent: dev.ua, platform: dev.name.startsWith('iphone') || dev.name.startsWith('wechat') ? 'iPhone' : 'Linux armv8l' });

  await cdp.send('Page.navigate', { url: `${BASE}/?mobilecheck=${dev.name}` });
  await waitLoad();
  await sleep(500);

  let m = await evaluate(metricsExpr);
  check('start screen shown', m.screen === 'start', m.screen);
  check('no horizontal overflow', !m.horizontalOverflow, `${m.docScrollWidth}/${m.bodyScrollWidth} vs ${m.innerWidth}`);
  check('start button in viewport', m.rects['#btn-start']?.inView, m.rects['#btn-start']);
  check('music toggle in viewport', m.rects['#btn-music-home']?.inView, m.rects['#btn-music-home']);
  check('no console/page errors on load', consoleErrors.length === 0 && pageErrors.length === 0, { consoleErrors: [...consoleErrors], pageErrors: [...pageErrors] });
  check('all JS/CSS resources loaded', !failedRequests.length, [...failedRequests]);
  check('bgm preloaded', m.resources.some((r) => r.name.includes('bgm-cat-bus.wav') && r.transferSize > 0), m.resources.filter((r) => r.name.includes('bgm')));
  await screenshot(`${dev.name}-start`);

  await tapSelector('#btn-start');
  await sleep(1300);
  m = await evaluate(metricsExpr);
  check('game screen after tap', m.screen === 'game', m.screen);
  check('level 1 loaded', m.state?.level === 1, m.state);
  check('no horizontal overflow in game', !m.horizontalOverflow, `${m.docScrollWidth}/${m.bodyScrollWidth} vs ${m.innerWidth}`);
  for (const s of ['#hud', '#queue', '#slots', '#board', '#btn-restart', '#btn-hint', '#btn-rescue', '#btn-mute', '#btn-music']) {
    check(`${s} visible+in viewport`, m.visibleKey[s] && m.rects[s]?.inView, m.rects[s]);
  }
  check('board below HUD (no overlap)', m.rects['#board'].y >= m.rects['#hud'].bottom - 1, { board: m.rects['#board'], hud: m.rects['#hud'] });
  check('no vehicle overlap', m.busOverlaps.length === 0, m.busOverlaps);
  check('BGM playing after user gesture', m.state?.bgmPlaying === true, m.state);
  check('BGM mode is local file', m.state?.bgmMode === 'file', m.state);
  await screenshot(`${dev.name}-game`);

  const movesBefore = m.state.moves;
  const busRect = await evaluate(`(() => { const el = document.querySelector('#board .bus.can-exit') || document.querySelector('#board .bus'); if (!el) return null; const r = el.getBoundingClientRect(); return { x:r.x+r.width/2, y:r.y+r.height/2, id: el.dataset.busId }; })()`);
  check('clickable bus exists', !!busRect, busRect);
  if (busRect) {
    await cdp.send('Input.dispatchMouseEvent', { type: 'mousePressed', x: busRect.x, y: busRect.y, button: 'left', buttons: 1, clickCount: 1 });
    await cdp.send('Input.dispatchMouseEvent', { type: 'mouseReleased', x: busRect.x, y: busRect.y, button: 'left', buttons: 0, clickCount: 1 });
    await sleep(900);
  }
  m = await evaluate(metricsExpr);
  check('bus tap increases moves', m.state?.moves > movesBefore, { before: movesBefore, after: m.state?.moves });

  await tapSelector('#btn-music');
  m = await evaluate(metricsExpr);
  check('music toggle turns BGM off', m.state?.bgmMuted === true, m.state);
  await tapSelector('#btn-music');
  m = await evaluate(metricsExpr);
  check('music toggle turns BGM back on', m.state?.bgmMuted === false, m.state);

  await tapSelector('#hud-level');
  await sleep(400);
  m = await evaluate(metricsExpr);
  check('level select opens', m.screen === 'levels', m.screen);
  check('level select no horizontal overflow', !m.horizontalOverflow, `${m.docScrollWidth} vs ${m.innerWidth}`);
  await screenshot(`${dev.name}-levels`);
  await tapSelector('#btn-levels-back');
  await sleep(300);
  m = await evaluate(metricsExpr);
  check('back returns to game', m.screen === 'game', m.screen);

  await tapSelector('#btn-restart');
  await sleep(400);
  m = await evaluate(metricsExpr);
  check('restart resets level', m.state?.level === 1 && m.state?.moves === 0, m.state);

  // Load level 50 in this viewport to catch dense-board overlap/overflow.
  await evaluate('window.__game.startLevel(49); true');
  await sleep(1200);
  m = await evaluate(metricsExpr);
  check('level 50 loads', m.state?.level === 50, m.state);
  check('level 50 no horizontal overflow', !m.horizontalOverflow, m.docScrollWidth);
  check('level 50 no vehicle overlap', m.busOverlaps.length === 0, m.busOverlaps.slice(0, 5));
  check('level 50 board fits viewport', m.rects['#board']?.inView, m.rects['#board']);
  await screenshot(`${dev.name}-level50`);

  // Refresh: must boot from start screen without broken resources.
  await cdp.send('Page.reload', { ignoreCache: true });
  await waitLoad();
  await sleep(500);
  m = await evaluate(metricsExpr);
  check('refresh boots start screen', m.screen === 'start', m.screen);
  check('refresh no horizontal overflow', !m.horizontalOverflow, m.docScrollWidth);
  check('refresh no new errors', consoleErrors.length === 0 && pageErrors.length === 0 && failedRequests.length === 0, { consoleErrors: [...consoleErrors], pageErrors: [...pageErrors], failedRequests: [...failedRequests] });

  result.metrics = m;
  result.errors = { consoleErrors: [...consoleErrors], pageErrors: [...pageErrors], failedRequests: [...failedRequests] };
  report.devices[dev.name] = result;

  // Reset error buffers between devices (errors on this document only).
  consoleErrors.length = 0;
  pageErrors.length = 0;
  failedRequests.length = 0;
  await cdp.send('Network.clearBrowserCache');
}

await writeFile(`${OUT}/report.json`, JSON.stringify(report, null, 2));

for (const [name, result] of Object.entries(report.devices)) {
  const failed = result.checks.filter((c) => !c.ok);
  console.log(`\n${failed.length ? '❌' : '✅'} ${name} — ${result.checks.length - failed.length}/${result.checks.length} checks`);
  for (const f of failed) console.log(`   FAIL ${f.name}: ${JSON.stringify(f.detail)}`);
}

console.log(`\nScreenshots: ${OUT}`);
console.log(hardFail ? 'RESULT: FAIL' : 'RESULT: PASS');

cdp.close();
chrome.kill('SIGTERM');
await sleep(200);
process.exit(hardFail ? 1 : 0);

