content.text:
  width: 38px; height: 22px; border-radius: 999px;
  background: #cfc3ac; position: relative; flex: none;
  transition: background .18s;
}
.music-toggle-knob {
  position: absolute; top: 2px; left: 2px; width: 18px; height: 18px;
  border-radius: 50%; background: #fff;
  box-shadow: 0 1px 4px rgba(60, 40, 10, .3);
  transition: transform .18s ease;
}
.music-toggle[aria-pressed="true"] .music-toggle-track { background: #42b96a; }
.music-toggle[aria-pressed="true"] .music-toggle-knob { transform: translateX(16px); }
.music-toggle.is-off { color: var(--ink-soft); }
.music-toggle.is-off .music-toggle-ico { opacity: .55; filter: grayscale(1); }

/* ===== 选关页 ===== */
#screen-levels {
  flex: 1; display: flex; flex-direction: column; gap: 10px;
  padding:
    calc(10px + env(safe-area-inset-top))
    calc(12px + env(safe-area-inset-right))
    calc(12px + env(safe-area-inset-bottom))
    calc(12px + env(safe-area-inset-left));
  min-height: 0;
}
#levels-head {
  display: flex; align-items: center; gap: 10px;
  background: var(--card); border-radius: 15px; padding: 9px 12px;
  box-shadow: 0 4px 12px rgba(90, 65, 20, .09);
  border: 1.5px solid var(--hairline);
}
#levels-head .btn { padding: 6px 12px; font-size: 13px; flex: none; }
.levels-title { flex: 1; display: flex; align-items: baseline; justify-content: center; gap: 8px; }
.levels-title h2 { margin: 0; font-size: 18px; }
.levels-count { color: var(--ink-soft); font-size: 12.5px; }
.level-grid {
  flex: 1; overflow-y: auto; min-height: 0;
  display: grid; grid-template-columns: repeat(auto-fill, minmax(76px, 1fr));
  gap: 8px; padding: 2px; align-content: start;
}
.level-cell {
  display: flex; flex-direction: column; align-items: center; gap: 2px;
  padding: 10px 4px 8px; border-radius: 15px;
  background: linear-gradient(180deg, #fffdf8, #fff8ea);
  border: 1.5px solid var(--hairline);
  box-shadow: 0 3px 0 #dccbaa; cursor: pointer; font-family: inherit;
  transition: transform .12s, filter .12s, box-shadow .12s;
}
.level-cell:active { transform: scale(.95); filter: brightness(.97); }
.level-cell.current {
  border-color: var(--accent);
  box-shadow: 0 3px 0 #dccbaa, 0 0 0 3px rgba(255, 159, 67, .3);
}
.level-no { font-size: 19px; font-weight: 900; color: var(--ink); }
.level-name {
  font-size: 11px; color: var(--ink-soft); max-width: 100%;
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.level-stars { font-size: 9px; color: var(--accent-deep); letter-spacing: 1px; min-height: 10px; }

/* HUD 关卡名按钮 */
.hud-level-btn {
  border: none; background: transparent; font-family: inherit;
  font-weight: 800; font-size: 15px; color: var(--ink);
  cursor: pointer; padding: 4px 6px; border-radius: 8px;
  max-width: 168px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
  transition: background .12s;
}
.hud-level-btn:active { background: #f0e4cc; }

/* ===== 游戏页布局 ===== */
#screen-game {
  flex: 1; display: flex; flex-direction: column; gap: 4px;
  padding:
    calc(6px + env(safe-area-inset-top))
    calc(8px + env(safe-area-inset-right))
    calc(6px + env(safe-area-inset-bottom))
    calc(8px + env(safe-area-inset-left));
  min-height: 0;
}

#hud {
  display: flex; align-items: center; gap: 6px;
  background: linear-gradient(180deg, #fffdf8, #fdf7ea);
  border-radius: 15px; padding: 7px 10px;
  box-shadow: 0 4px 12px rgba(90, 65, 20, .09);
  border: 1.5px solid var(--hairline);
  flex: none;
}
.hud-left { font-weight: 800; font-size: 15px; min-width: 0; flex: 1 1 auto; }
.hud-mid { flex: 0 0 auto; color: var(--ink-soft); font-size: 12px; text-align: center; white-space: nowrap; }
.hud-right { display: flex; gap: 5px; flex: none; }
.hud-right .btn { padding: 6px 9px; font-size: 12px; border-radius: 10px; white-space: nowrap; min-height: 36px; touch-action: manipulation; }
.hud-right .btn-icon { padding: 6px 7px; font-size: 15px; line-height: 1; }
.btn-icon.btn-music { position: relative; }
.btn-music.is-off { opacity: .55; filter: grayscale(.6); }
.btn-music.is-off::after {
  content: ""; position: absolute; left: 50%; top: 50%;
  width: 22px; height: 2px; border-radius: 2px; background: #e8554d;
  transform: translate(-50%, -50%) rotate(-42deg);
  pointer-events: none;
  justify-content: center;
}
.slot {
  width: 100%; min-width: 0; height: clamp(62px, 9.5vh, 96px);
  border-radius: 17px;
  background:
    repeating-linear-gradient(-45deg, rgba(255,255,255,.34) 0 6px, rgba(255,255,255,0) 6px 12px),
    linear-gradient(180deg, #f7ead2, var(--slot-bg));
  box-shadow: inset 0 2px 6px rgba(120,90,40,.12), 0 4px 10px rgba(90,70,20,.08);
  display: flex; flex-direction: column; align-items: center; justify-content: flex-end;
  position: relative; border: 2px solid #e7d7b7;
  padding: 4px 5px 5px;
  overflow: hidden;
}
.slot::after {
  content: ""; position: absolute; left: 8px; right: 8px; bottom: 3px; height: 3px;
  border-radius: 2px;
  background: repeating-linear-gradient(90deg, #d8c49b 0 8px, transparent 8px 13px);
  opacity: .8;
}
.slot-empty {
  width: 100%; height: 100%; display: flex; flex-direction: column; gap: 2px;
  align-items: center; justify-content: center;
  border: 2px dashed #d5c29a; border-radius: 13px; color: #b9a67e;
  font-size: 12px; font-weight: 800;
}
.slot-paw { font-size: 18px; opacity: .65; }
.slot-incoming { border-style: solid; border-color: #e3d2ad; color: #a18c61; }
.slot-extra {
  border-color: #f0b45a;
  background:
    repeating-linear-gradient(-45deg, rgba(255,214,140,.24) 0 6px, rgba(255,255,255,0) 6px 12px),
    linear-gradient(180deg, #fff4dd, #ffe9c4);
  box-shadow: inset 0 2px 6px rgba(180,120,30,.14), 0 4px 10px rgba(160,105,20,.12), 0 0 0 2px rgba(255,181,88,.28);
}
.slot-extra-badge {
  position: absolute; top: 3px; left: 50%; transform: translateX(-50%);
  z-index: 5; pointer-events: none;
  font-size: 9px; font-weight: 900; letter-spacing: .5px;
  color: #8a5310; background: #ffd166; border: 1px solid #e7a93d;
  border-radius: 999px; padding: 1px 6px;
  box-shadow: 0 2px 4px rgba(120,70,10,.16);
}
.slot-extra .slot-empty { border-color: #e6c184; color: #b0823d; }
/* 5–6 个车位（含临时位）时缩小内部元素，保证一屏放下 */
#slots.slots-many .slot { border-radius: 13px; padding: 3px 3px 4px; }
#slots.slots-many .slot-load { font-size: 9px; padding: 1px 4px; }
#slots.slots-many .slot-load b { font-size: 11.5px; }
#slots.slots-many .slot-load-paw { display: none; }
