#slots.slots-many .slot-extra-badge { font-size: 8px; padding: 1px 4px; }
.slot-incoming .slot-paw { opacity: .8; animation: slotIncomingPulse 1s ease-in-out infinite; }
@keyframes slotIncomingPulse { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-2px); } }
